:root{
  --ink:#05070b;
  --paper:#ece5d3;
  --green:#8dffb2;
  --green-dim:#3d8f5c;
  --red:#ff3448;
  --amber:#ffcf6b;
  --dim:#7d8a80;
  --mono:"Courier New", Courier, monospace;
  --display:"Arial Black","Archivo Black",Impact,sans-serif;
  --safe-l:env(safe-area-inset-left,0px);
  --safe-r:env(safe-area-inset-right,0px);
  --safe-t:env(safe-area-inset-top,0px);
  --safe-b:env(safe-area-inset-bottom,0px);
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{margin:0;padding:0;width:100%;height:100%;overflow:hidden;background:#05060a;color:var(--paper);font-family:var(--mono)}
body{-webkit-user-select:none;user-select:none;touch-action:none}
#app{position:fixed;inset:0;overflow:hidden;background:radial-gradient(120% 100% at 50% 20%,#111a17 0%,#05070b 70%)}
#scene{position:absolute;inset:0;width:100%;height:100%;display:block}
.hidden{display:none !important}
button{font-family:var(--mono);cursor:pointer;border:none;outline:none}

/* ---------- FX ---------- */
#fx-vignette{position:absolute;inset:0;pointer-events:none;z-index:3;
  background:radial-gradient(ellipse at 50% 50%,rgba(0,0,0,0) 42%,rgba(0,0,0,.55) 78%,rgba(0,0,0,.92) 100%);}
#fx-grain{position:absolute;inset:-20%;pointer-events:none;z-index:4;opacity:.10;mix-blend-mode:overlay;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='220' height='220'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%25' height='100%25' filter='url(%23n)' opacity='.9'/></svg>");
  animation:grain .5s steps(2) infinite}
@keyframes grain{0%{transform:translate(0,0)}25%{transform:translate(-2%,1%)}50%{transform:translate(1%,-2%)}75%{transform:translate(2%,2%)}100%{transform:translate(-1%,-1%)}}
#fx-scan{position:absolute;inset:0;pointer-events:none;z-index:4;opacity:.10;
  background:repeating-linear-gradient(0deg,rgba(255,255,255,.06) 0 1px,transparent 1px 3px)}
#fx-blood{position:absolute;inset:0;pointer-events:none;z-index:5;opacity:0;transition:opacity .25s ease;
  background:radial-gradient(ellipse at 50% 50%,rgba(90,0,8,0) 35%,rgba(150,0,14,.55) 85%,rgba(60,0,6,.9) 100%)}
#fx-flash{position:absolute;inset:0;pointer-events:none;z-index:8;opacity:0;background:#fff}
#fx-flash.fire{animation:flashbang .5s ease-out}
@keyframes flashbang{0%{opacity:.95}100%{opacity:0}}

/* ---------- HUD ---------- */
#hud{position:absolute;inset:0;z-index:6;pointer-events:none;
  padding:calc(18px + var(--safe-t)) calc(18px + var(--safe-r)) calc(16px + var(--safe-b)) calc(18px + var(--safe-l));
  font-family:var(--mono)}
.label{font-size:10px;letter-spacing:.22em;color:var(--green-dim);margin-bottom:4px}
#objective-panel{position:absolute;top:calc(18px + var(--safe-t));left:calc(18px + var(--safe-l));max-width:min(340px,46vw);
  background:linear-gradient(90deg,rgba(4,10,7,.82),rgba(4,10,7,.35));border-left:2px solid var(--green);
  padding:9px 14px 10px 12px;box-shadow:0 0 30px rgba(0,0,0,.4)}
#objective-text{font-size:13px;line-height:1.4;letter-spacing:.03em;color:#eafff1;text-shadow:0 0 10px rgba(141,255,178,.25)}
#objective-sub{font-size:10px;color:#7e9a88;margin-top:4px;letter-spacing:.06em}
#map-panel{position:absolute;top:calc(16px + var(--safe-t));right:calc(16px + var(--safe-r));
  background:rgba(3,8,6,.66);border:1px solid rgba(141,255,178,.22);padding:7px 8px 8px;backdrop-filter:blur(2px)}
#map-panel .label{display:flex;justify-content:space-between;gap:14px;margin-bottom:5px}
#note-count{color:var(--amber);letter-spacing:.12em}
#minimap{display:block;width:180px;height:130px;image-rendering:pixelated}
#crosshair{position:absolute;left:50%;top:50%;width:4px;height:4px;margin:-2px 0 0 -2px;border-radius:50%;
  background:rgba(230,255,240,.7);box-shadow:0 0 6px rgba(141,255,178,.7);transition:transform .15s}
#crosshair.hot{transform:scale(2.6);background:var(--amber);box-shadow:0 0 12px var(--amber)}
#status-panel{position:absolute;left:calc(18px + var(--safe-l));bottom:calc(18px + var(--safe-b));width:min(230px,42vw);opacity:.92}
.meter-row{display:flex;align-items:center;gap:8px;margin-bottom:5px}
.meter-label{width:52px;font-size:9px;letter-spacing:.18em;color:#8fa99a}
.meter{flex:1;height:5px;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.06);overflow:hidden}
.meter i{display:block;height:100%;width:0%;transition:width .12s linear;background:var(--green)}
#noise-fill{background:linear-gradient(90deg,#68d9a1,#ffd166)}
#stamina-fill{background:linear-gradient(90deg,#69b7ff,#8dffb2)}
#battery-fill{background:linear-gradient(90deg,#ff9f43,#ffcf6b)}
#torch-state{font-size:9px;letter-spacing:.18em;color:#5e7466;margin-top:7px}
#torch-state.on{color:var(--amber);text-shadow:0 0 8px rgba(255,207,107,.4)}
#prompt{position:absolute;left:50%;bottom:24%;transform:translateX(-50%);font-size:12px;letter-spacing:.14em;
  background:rgba(2,7,5,.8);border:1px solid rgba(141,255,178,.3);padding:8px 14px;color:#dfffe9;opacity:0;transition:opacity .15s;white-space:nowrap}
#prompt.show{opacity:1}
#prompt b{color:var(--amber)}
#subtitle-wrap{position:absolute;left:50%;bottom:calc(7% + var(--safe-b));transform:translateX(-50%);width:min(760px,88vw);text-align:center;
  text-shadow:0 2px 8px #000,0 0 20px #000;opacity:0;transition:opacity .25s}
#subtitle-wrap.show{opacity:1}
#speaker{font-size:11px;letter-spacing:.26em;color:var(--green);margin-bottom:5px;text-transform:uppercase}
#subtitle{font-size:16px;line-height:1.5;color:#f4efe2;min-height:24px}
#subtitle .em{color:var(--amber)}
#subtitle .scare{color:#ff8b96;font-weight:bold;letter-spacing:.04em}
#toast{position:absolute;top:18%;left:50%;transform:translate(-50%,-10px);font-size:12px;letter-spacing:.14em;
  background:rgba(4,10,7,.88);border:1px solid rgba(255,207,107,.4);color:var(--amber);padding:8px 16px;opacity:0;transition:all .35s;white-space:nowrap}
#toast.show{opacity:1;transform:translate(-50%,0)}
#detection{position:absolute;top:19%;left:50%;transform:translateX(-50%);text-align:center;color:var(--red);
  font-family:var(--display);font-size:12px;letter-spacing:.3em;opacity:0;transition:opacity .12s}
#detection span:first-child{display:block;font-size:34px;line-height:1;text-shadow:0 0 22px rgba(255,52,72,.8)}
#detection.show{opacity:1;animation:det .5s infinite alternate}
@keyframes det{from{filter:brightness(1)}to{filter:brightness(1.7)}}
#stamina-flash{position:absolute;inset:0;pointer-events:none;opacity:0;transition:opacity .4s;
  background:radial-gradient(ellipse at 50% 60%,transparent 40%,rgba(30,4,8,.5) 100%)}

/* ---------- screens ---------- */
.screen{position:absolute;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;
  background:radial-gradient(ellipse at 50% 40%,rgba(6,12,9,.55) 0%,rgba(2,4,5,.9) 70%,rgba(1,2,3,.97) 100%)}
#title-screen{background:linear-gradient(180deg,rgba(2,4,6,.55) 0%,rgba(2,4,6,.15) 35%,rgba(2,4,6,.88) 100%)}
.title-inner{text-align:center;padding:24px;animation:titleIn 1.4s ease both}
@keyframes titleIn{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
.kicker{font-size:10px;letter-spacing:.5em;color:#8fa99a;margin-bottom:14px}
#title-screen h1{font-family:var(--display);font-size:clamp(64px,15vw,190px);line-height:.82;margin:0;letter-spacing:.03em;
  color:#eef7e9;text-shadow:0 0 2px #fff,0 0 38px rgba(141,255,178,.25),0 12px 0 rgba(0,0,0,.35)}
#title-screen h1::after{content:"";display:block;height:2px;margin:16px auto 0;width:44%;background:linear-gradient(90deg,transparent,var(--green),transparent)}
.subtitle{font-size:clamp(12px,2vw,18px);letter-spacing:.62em;color:var(--green);margin-top:14px;text-shadow:0 0 16px rgba(141,255,178,.5)}
.tagline{margin-top:30px;font-size:13px;line-height:1.9;color:#c9d6cd;letter-spacing:.06em}
.tagline span{color:#7d9486;font-size:11px}
.btn-row{display:flex;gap:14px;justify-content:center;margin-top:30px;flex-wrap:wrap}
.big-btn{background:linear-gradient(180deg,#a9ffc4,#62d78d);color:#04130a;padding:15px 34px;font-size:13px;font-weight:bold;
  letter-spacing:.22em;border:1px solid #d6ffe3;box-shadow:0 0 30px rgba(98,215,141,.3),0 6px 0 rgba(0,0,0,.4);transition:all .15s}
.big-btn:hover{transform:translateY(-2px);box-shadow:0 0 46px rgba(98,215,141,.5),0 8px 0 rgba(0,0,0,.4)}
.big-btn:active{transform:translateY(1px);box-shadow:0 0 20px rgba(98,215,141,.3),0 3px 0 rgba(0,0,0,.4)}
.ghost-btn{background:rgba(255,255,255,.03);color:#cfe3d6;padding:14px 22px;font-size:11px;letter-spacing:.2em;
  border:1px solid rgba(207,227,214,.25);transition:all .15s}
.ghost-btn:hover{border-color:var(--green);color:#fff;background:rgba(141,255,178,.07)}
.title-note{margin-top:30px;font-size:10px;letter-spacing:.16em;color:#5f7368}
.credits-corner{position:absolute;bottom:18px;right:22px;font-size:9px;letter-spacing:.24em;color:#4c5c52}
.panel{width:min(740px,90vw);background:linear-gradient(180deg,rgba(9,17,13,.95),rgba(4,9,6,.97));
  border:1px solid rgba(141,255,178,.22);padding:30px 34px;box-shadow:0 30px 80px rgba(0,0,0,.7)}
.panel.narrow{width:min(460px,90vw);text-align:center}
.panel h2{font-family:var(--display);font-size:34px;letter-spacing:.08em;margin:0 0 8px;color:#eff9f1}
.muted{color:#7d9486;font-size:12px;line-height:1.7;margin:0 0 22px}
.controls-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px 26px;margin:22px 0 20px}
.controls-grid div{display:flex;align-items:center;gap:12px;border-bottom:1px dashed rgba(255,255,255,.08);padding-bottom:8px}
.controls-grid kbd{min-width:92px;text-align:center;background:#0d1712;border:1px solid #2a4234;color:var(--green);padding:5px 7px;font-size:10px;letter-spacing:.1em;font-family:var(--mono)}
.controls-grid span{font-size:12px;color:#b9ccc0}
.controls-tips{font-size:11.5px;line-height:1.75;color:#93a89a;margin-bottom:22px}
.controls-tips b{color:var(--green)}
.pause-buttons{display:flex;flex-direction:column;gap:10px;align-items:stretch;margin:18px 0}
.slider-row{display:flex;align-items:center;gap:12px;margin-top:10px;font-size:10px;letter-spacing:.18em;color:#8fa99a}
.slider-row input{flex:1;accent-color:#8dffb2}

/* caught / win */
#caught-screen{background:radial-gradient(ellipse at 50% 45%,rgba(70,0,8,.55),rgba(4,0,2,.97) 70%)}
.caught-inner{text-align:center;padding:24px;animation:caughtIn .6s ease both}
@keyframes caughtIn{from{transform:scale(1.06);opacity:0;filter:blur(6px)}to{transform:none;opacity:1;filter:none}}
.caught-kicker{font-size:10px;letter-spacing:.44em;color:#ff6b7b}
#caught-screen h2{font-family:var(--display);font-size:clamp(64px,12vw,150px);margin:12px 0 0;color:#ffe9e9;
  text-shadow:0 0 40px rgba(255,52,72,.45)}
#caught-line{font-size:16px;color:#ffc3c9;margin-top:10px;letter-spacing:.05em}
#caught-tip{margin:22px auto 30px;max-width:560px;font-size:11.5px;line-height:1.7;color:#a78d90}
#win-screen{background:radial-gradient(ellipse at 50% 35%,rgba(20,60,40,.4),rgba(2,5,4,.98) 70%)}
.win-inner{text-align:center;padding:24px;animation:titleIn 1s ease both}
.win-kicker{font-size:10px;letter-spacing:.5em;color:var(--green)}
#win-screen h1{font-family:var(--display);font-size:clamp(54px,11vw,140px);margin:10px 0 4px;color:#f0fff4;text-shadow:0 0 40px rgba(141,255,178,.35)}
#win-grade{font-size:13px;letter-spacing:.4em;color:var(--amber);margin-bottom:18px}
#win-stats{font-size:11.5px;line-height:2;color:#9fb3a5;margin-bottom:14px}
#win-line{font-size:13px;color:#d6e4da;margin-bottom:28px}
.win-small{margin-top:22px;font-size:9px;letter-spacing:.2em;color:#5c7265}

/* report card */
.overlay{position:absolute;inset:0;z-index:24;display:flex;align-items:center;justify-content:center;pointer-events:none}
#report-card{background:rgba(2,4,3,.55);backdrop-filter:blur(3px)}
#report-card .card{width:min(560px,88vw);background:linear-gradient(160deg,#f1e9d2,#ded4ba);color:#1d211b;padding:28px 30px 24px;
  transform:rotate(-1.6deg);box-shadow:0 30px 70px rgba(0,0,0,.65),inset 0 0 60px rgba(120,100,60,.18);position:relative;
  border:1px solid #b9ad8e;animation:cardIn .55s cubic-bezier(.2,1.4,.4,1) both;font-family:var(--mono)}
@keyframes cardIn{from{opacity:0;transform:rotate(-7deg) translateY(30px) scale(.92)}to{opacity:1;transform:rotate(-1.6deg) scale(1)}}
#report-card .card-head{display:flex;justify-content:space-between;font-size:9px;letter-spacing:.14em;border-bottom:2px solid #2d332a;padding-bottom:7px}
#report-card .card-name{font-size:12px;letter-spacing:.14em;margin:12px 0 10px;font-weight:bold}
#report-card .card-rows{display:flex;flex-direction:column;gap:0}
#report-card .row{display:flex;align-items:baseline;gap:8px;border-bottom:1px dashed #9d927a;padding:5px 0;font-size:14px;letter-spacing:.04em}
#report-card .row .subject{flex:1;font-weight:bold}
#report-card .row .grade{font-family:var(--display);font-size:22px;min-width:46px;text-align:right}
#report-card .row .grade.bad{color:#a1151c}
#report-card .row .grade.weird{color:#6a2f8c;animation:weird 1s infinite alternate}
#report-card .row .grade.zed{color:#2c6e3d}
@keyframes weird{from{transform:skewX(0)}to{transform:skewX(-14deg) scale(1.15)}}
#report-card .card-foot{margin-top:14px;font-size:9px;letter-spacing:.1em;color:#4a4a3d}
#report-card .card-stamp{position:absolute;right:22px;bottom:18px;width:92px;height:92px;border:3px solid rgba(160,20,25,.55);
  border-radius:50%;display:flex;align-items:center;justify-content:center;font-family:var(--display);font-size:56px;color:rgba(160,20,25,.65);
  transform:rotate(-14deg);box-shadow:0 0 0 2px rgba(160,20,25,.2) inset}
#note-popup{background:rgba(2,4,3,.62);backdrop-filter:blur(3px);pointer-events:auto;cursor:pointer}
.note{width:min(440px,86vw);background:#efe6c9;color:#22261f;padding:26px 26px 18px;transform:rotate(1.2deg);
  box-shadow:0 26px 60px rgba(0,0,0,.6);animation:cardIn .4s ease both;position:relative;font-family:var(--mono)}
.note-pin{position:absolute;top:-12px;left:50%;transform:translateX(-50%);font-size:22px}
.note-title{font-size:10px;letter-spacing:.28em;color:#8a6b2c;margin-bottom:10px}
.note-body{font-size:16px;line-height:1.6;white-space:pre-wrap}
.note-hint{margin-top:18px;font-size:9px;letter-spacing:.16em;color:#8c856d;border-top:1px dashed #b3a98a;padding-top:10px}

#letterbox{position:absolute;inset:0;z-index:16;pointer-events:none;pointer-events:none}
#letterbox .bar{position:absolute;left:0;right:0;height:9vh;background:#000;transition:transform .7s cubic-bezier(.6,0,.2,1)}
#letterbox .bar.top{top:0;transform:translateY(-100%)}
#letterbox .bar.bottom{bottom:0;transform:translateY(100%)}
#letterbox.on .bar.top,#letterbox.on .bar.bottom{transform:none}
#fade{position:absolute;inset:0;z-index:22;background:#000;opacity:0;pointer-events:none;transition:opacity .75s}
#fade.on{opacity:1}
#chapter-card{position:absolute;left:0;right:0;top:38%;z-index:18;text-align:center;pointer-events:none;opacity:0;transition:opacity .8s}
#chapter-card.show{opacity:1}
.chapter-kicker{font-size:10px;letter-spacing:.5em;color:var(--green);margin-bottom:10px}
.chapter-title{font-family:var(--display);font-size:clamp(30px,6vw,64px);letter-spacing:.06em;color:#f2fbef;text-shadow:0 0 40px rgba(141,255,178,.2)}

/* touch */
#touch-ui{position:absolute;inset:0;z-index:12;pointer-events:none}
#stick-zone{position:absolute;left:calc(14px + var(--safe-l));bottom:calc(20px + var(--safe-b));width:140px;height:140px;pointer-events:auto}
#stick-base{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(141,255,178,.25);background:rgba(4,10,7,.3)}
#stick-knob{position:absolute;left:50%;top:50%;width:54px;height:54px;margin:-27px 0 0 -27px;border-radius:50%;
  background:rgba(141,255,178,.22);border:1px solid rgba(141,255,178,.5)}
#touch-buttons{position:absolute;right:calc(14px + var(--safe-r));bottom:calc(22px + var(--safe-b));display:flex;flex-wrap:wrap;gap:10px;
  width:210px;justify-content:flex-end;pointer-events:auto}
.tbtn{width:86px;height:46px;border-radius:8px;background:rgba(4,10,7,.62);border:1px solid rgba(141,255,178,.3);color:#cfead7;font-size:10px;letter-spacing:.16em}
.tbtn:active{background:rgba(141,255,178,.2)}
.tbtn.interact{background:rgba(141,255,178,.16);border-color:rgba(141,255,178,.7);color:#eaffef}
@media (pointer:coarse){
  #status-panel{width:180px;bottom:calc(174px + var(--safe-b))}
  #map-panel{transform:scale(.8);transform-origin:top right}
  #objective-panel{max-width:44vw;font-size:11px}
  #prompt{bottom:32%}
  #subtitle{font-size:14px}
}

/* loading */
#loading{background:#040604;z-index:40;transition:opacity .6s}
#loading.out{opacity:0;pointer-events:none}
.load-inner{text-align:center}
.load-logo{font-family:var(--display);font-size:clamp(38px,8vw,74px);letter-spacing:.04em;color:#dff0e4;opacity:.9}
.load-bar{width:min(320px,70vw);height:3px;background:rgba(255,255,255,.1);margin:22px auto 14px;overflow:hidden}
.load-bar i{display:block;height:100%;width:35%;background:var(--green);animation:load 1.1s ease-in-out infinite}
@keyframes load{0%{transform:translateX(-120%)}100%{transform:translateX(320%)}}
.load-text{font-size:10px;letter-spacing:.3em;color:#6d8476}

@media (max-width:700px){
  #objective-panel{max-width:52vw}
  #objective-text{font-size:11px}
  #objective-sub{display:none}
  .controls-grid{grid-template-columns:1fr}
  .panel{padding:22px}
  #title-screen h1{letter-spacing:0}
  .tagline{margin-top:20px}
  #subtitle{font-size:13.5px}
  #subtitle-wrap{bottom:calc(9% + var(--safe-b))}
}

// Procedural audio engine — no external assets.
export class AudioFX {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.volume = 0.7;
    this.muted = false;
    this.started = false;
    this.noiseBuf = null;
    this.ambience = null;
    this.heart = null;
    this.alarm = null;
    this.lastStep = 0;
  }

  init() {
    if (this.ctx) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.volume;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 24;
    comp.ratio.value = 4;
    comp.attack.value = 0.004;
    comp.release.value = 0.25;
    this.master.connect(comp).connect(this.ctx.destination);
    this.noiseBuf = this.makeNoise(2.2);
  }

  resume() {
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume();
  }

  setVolume(v) {
    this.volume = v;
    if (this.master) this.master.gain.setTargetAtTime(this.muted ? 0 : v, this.ctx.currentTime, 0.05);
  }

  toggleMute() {
    this.muted = !this.muted;
    this.setVolume(this.volume);
    return this.muted;
  }

  makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      d[i] = last * 3.2;
    }
    return buf;
  }

  noise(dur = 0.2, gain = 0.2, filterFreq = 1200, type = 'lowpass', start = null) {
    if (!this.ctx) return;
    const t = start ?? this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    src.loop = true;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.value = filterFreq;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f).connect(g).connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.05);
    return { src, g, f };
  }

  tone(freq, dur = 0.2, gain = 0.12, type = 'sine', slideTo = null, start = null) {
    if (!this.ctx) return;
    const t = start ?? this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(this.master);
    o.start(t);
    o.stop(t + dur + 0.05);
    return o;
  }

  startAmbience() {
    if (!this.ctx || this.started) return;
    this.started = true;
    const t = this.ctx.currentTime;

    const bus = this.ctx.createGain();
    bus.gain.value = 0.0;
    bus.gain.setTargetAtTime(1, t, 2.5);
    bus.connect(this.master);

    // Low detuned drone
    const droneGain = this.ctx.createGain();
    droneGain.gain.value = 0.055;
    const lp = this.ctx.createBiquadFilter();
    lp.type = 'lowpass'; lp.frequency.value = 320; lp.Q.value = 3;
    [36.7, 55.0, 73.4].forEach((f, i) => {
      const o = this.ctx.createOscillator();
      o.type = i === 2 ? 'triangle' : 'sawtooth';
      o.frequency.value = f;
      o.detune.value = (i - 1) * 7;
      const g = this.ctx.createGain();
      g.gain.value = i === 0 ? 0.5 : 0.22;
      o.connect(g).connect(lp);
      o.start();
    });
    lp.connect(droneGain).connect(bus);

    // slow LFO on drone gain
    const lfo = this.ctx.createOscillator();
    lfo.frequency.value = 0.055;
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.value = 0.025;
    lfo.connect(lfoGain).connect(droneGain.gain);
    lfo.start();

    // Fluorescent hum
    const hum = this.ctx.createOscillator();
    hum.type = 'sine'; hum.frequency.value = 120;
    const humG = this.ctx.createGain(); humG.gain.value = 0.008;
    hum.connect(humG).connect(bus);
    hum.start();

    this.ambience = { bus, droneGain, lp };

    // Occasional creaks
    this.creakTimer = setInterval(() => {
      if (!this.ctx || this.muted) return;
      const r = Math.random();
      if (r < 0.45) {
        this.noise(0.5 + Math.random() * 0.8, 0.035 + Math.random() * 0.03, 260 + Math.random() * 500, 'bandpass');
      } else if (r < 0.62) {
        this.tone(60 + Math.random() * 40, 0.6, 0.025, 'sine', 40);
      }
    }, 5200);
  }

  stopAmbience() {
    this.started = false;
    if (this.creakTimer) clearInterval(this.creakTimer);
    if (this.ambience) {
      try {
        this.ambience.bus.gain.setTargetAtTime(0, this.ctx.currentTime, 0.4);
      } catch {}
      this.ambience = null;
    }
  }

  setTension(amount) {
    if (!this.ambience) return;
    const t = this.ctx.currentTime;
    this.ambience.droneGain.gain.setTargetAtTime(0.05 + amount * 0.10, t, 0.6);
    this.ambience.lp.frequency.setTargetAtTime(300 + amount * 700, t, 0.8);
  }

  footstep(sprint = false, crouch = false) {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    if (now - this.lastStep < 0.09) return;
    this.lastStep = now;
    const vol = crouch ? 0.03 : sprint ? 0.16 : 0.085;
    const f = crouch ? 420 : sprint ? 1300 : 800;
    this.noise(crouch ? 0.09 : 0.13, vol, f, 'lowpass');
    this.tone(crouch ? 60 : 85, 0.09, crouch ? 0.02 : 0.05, 'sine', 40);
  }

  heartbeat(intensity = 0.4) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this.tone(48, 0.16, 0.07 + intensity * 0.12, 'sine', 32, t);
    this.tone(42, 0.20, 0.05 + intensity * 0.10, 'sine', 28, t + 0.22);
  }

  whistle() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this.tone(1780, 0.28, 0.12, 'sine', 2100, t);
    this.tone(2050, 0.4, 0.09, 'sine', 1650, t + 0.24);
  }

  growl() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this.noise(1.2, 0.16, 180, 'lowpass');
    this.tone(58, 1.3, 0.12, 'sawtooth', 31, t);
    this.tone(87, 1.1, 0.05, 'square', 44, t + 0.1);
  }

  scare() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this.noise(1.4, 0.35, 4200, 'highpass');
    this.tone(1400, 0.9, 0.16, 'sawtooth', 90, t);
    this.tone(740, 1.2, 0.12, 'square', 55, t + 0.02);
    this.tone(210, 1.5, 0.18, 'sine', 40, t + 0.05);
    this.noise(2.2, 0.2, 320, 'lowpass', t + 0.2);
  }

  stinger() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this.tone(110, 0.8, 0.09, 'sine', 55, t);
    this.tone(220, 0.6, 0.05, 'triangle', 165, t + 0.08);
    this.noise(0.7, 0.06, 900, 'bandpass', t + 0.05);
  }

  ui() { this.tone(660, 0.07, 0.05, 'square', 880); }
  pickup() {
    if (!this.ctx) return;
    [880, 1320, 1760].forEach((f, i) => this.tone(f, 0.18, 0.06, 'sine', f * 1.02, this.ctx.currentTime + i * 0.06));
  }
  unlock() {
    if (!this.ctx) return;
    this.noise(0.12, 0.12, 2400, 'bandpass');
    this.tone(320, 0.12, 0.07, 'square', 220, this.ctx.currentTime + 0.12);
    this.tone(180, 0.3, 0.09, 'sawtooth', 120, this.ctx.currentTime + 0.25);
  }
  door() {
    if (!this.ctx) return;
    this.noise(0.55, 0.07, 700, 'bandpass');
    this.tone(120, 0.4, 0.03, 'sine', 80);
  }
  hide() {
    if (!this.ctx) return;
    this.noise(0.3, 0.09, 500, 'lowpass');
    this.tone(90, 0.2, 0.03, 'sine', 55);
  }
  breath() {
    if (!this.ctx) return;
    this.noise(0.42, 0.045, 900, 'bandpass');
  }
  alarmStart() {
    if (!this.ctx || this.alarm) return;
    const bus = this.ctx.createGain();
    bus.gain.value = 0.055;
    bus.connect(this.master);
    const o = this.ctx.createOscillator();
    o.type = 'sawtooth';
    o.frequency.value = 420;
    const lfo = this.ctx.createOscillator();
    lfo.type = 'sine'; lfo.frequency.value = 0.55;
    const lg = this.ctx.createGain(); lg.gain.value = 170;
    lfo.connect(lg).connect(o.frequency);
    const f = this.ctx.createBiquadFilter();
    f.type = 'lowpass'; f.frequency.value = 1100;
    o.connect(f).connect(bus);
    o.start(); lfo.start();
    this.alarm = { bus, o, lfo };
  }
  alarmStop() {
    if (!this.alarm) return;
    const t = this.ctx.currentTime;
    this.alarm.bus.gain.setTargetAtTime(0, t, 0.3);
    setTimeout(() => {
      try { this.alarm.o.stop(); this.alarm.lfo.stop(); } catch {}
      this.alarm = null;
    }, 800);
  }
  chaseStart() {
    if (!this.ctx || this.chase) return;
    const bus = this.ctx.createGain();
    bus.gain.value = 0.0;
    bus.gain.setTargetAtTime(0.10, this.ctx.currentTime, 0.3);
    bus.connect(this.master);
    const o1 = this.ctx.createOscillator(); o1.type = 'sawtooth'; o1.frequency.value = 73;
    const o2 = this.ctx.createOscillator(); o2.type = 'square'; o2.frequency.value = 77.5;
    const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 500;
    const trem = this.ctx.createOscillator(); trem.type = 'sine'; trem.frequency.value = 7.5;
    const tg = this.ctx.createGain(); tg.gain.value = 0.04;
    const vca = this.ctx.createGain(); vca.gain.value = 1;
    trem.connect(tg).connect(vca.gain);
    o1.connect(f); o2.connect(f); f.connect(vca).connect(bus);
    o1.start(); o2.start(); trem.start();
    this.chase = { bus, o1, o2, trem };
  }
  chaseStop() {
    if (!this.chase) return;
    const c = this.chase;
    this.chase = null;
    if (!this.ctx) return;
    c.bus.gain.setTargetAtTime(0, this.ctx.currentTime, 0.35);
    setTimeout(() => { try { c.o1.stop(); c.o2.stop(); c.trem.stop(); } catch {} }, 900);
  }
  win() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    [261.6, 329.6, 392, 523.3].forEach((f, i) => this.tone(f, 1.4, 0.09, 'triangle', f, t + i * 0.16));
  }
  typeBlip(pitch = 1) {
    if (!this.ctx) return;
    this.tone(420 * pitch + Math.random() * 80, 0.03, 0.014, 'square');
  }
}

export const audio = new AudioFX();

import * as THREE from 'three';

function canvas(w, h) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return [c, c.getContext('2d')];
}

function tex(c, repeatX = 1, repeatY = 1) {
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repeatX, repeatY);
  t.anisotropy = 8;
  return t;
}

function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function speckle(g, w, h, count, colors, alpha = 0.15, size = 2) {
  const r = rng(count * 977 + w);
  for (let i = 0; i < count; i++) {
    g.globalAlpha = alpha * (0.3 + r());
    g.fillStyle = colors[(r() * colors.length) | 0];
    const s = size * (0.4 + r() * 1.6);
    g.fillRect(r() * w, r() * h, s, s);
  }
  g.globalAlpha = 1;
}

const cache = new Map();
function cached(key, fn) {
  if (!cache.has(key)) cache.set(key, fn());
  return cache.get(key);
}

export const T = {
  floor: (variant = 0) => cached('floor' + variant, () => {
    const [c, g] = canvas(512, 512);
    const base = variant === 1 ? '#9d9a8b' : variant === 2 ? '#a9b3a0' : '#b4b2a2';
    g.fillStyle = base; g.fillRect(0, 0, 512, 512);
    const r = rng(42 + variant);
    for (let y = 0; y < 4; y++) for (let x = 0; x < 4; x++) {
      const shade = 0.94 + r() * 0.11;
      g.fillStyle = `rgba(${Math.floor(150 * shade)},${Math.floor(152 * shade)},${Math.floor(135 * shade)},.35)`;
      g.fillRect(x * 128 + 2, y * 128 + 2, 124, 124);
    }
    g.strokeStyle = 'rgba(60,62,50,.30)'; g.lineWidth = 2;
    for (let i = 0; i <= 4; i++) {
      g.beginPath(); g.moveTo(i * 128, 0); g.lineTo(i * 128, 512); g.stroke();
      g.beginPath(); g.moveTo(0, i * 128); g.lineTo(512, i * 128); g.stroke();
    }
    speckle(g, 512, 512, 1500, ['#6c6b5c', '#d7d5c2', '#4b4c40'], 0.22, 1.8);
    // scuff marks
    for (let i = 0; i < 14; i++) {
      g.globalAlpha = 0.08 + r() * 0.1;
      g.strokeStyle = '#3d3d32'; g.lineWidth = 1 + r() * 2;
      g.beginPath();
      const x = r() * 512, y = r() * 512;
      g.moveTo(x, y); g.quadraticCurveTo(x + r() * 80 - 40, y + r() * 40, x + r() * 120 - 60, y + r() * 60);
      g.stroke();
    }
    g.globalAlpha = 1;
    return tex(c, 3, 3);
  }),

  carpet: () => cached('carpet', () => {
    const [c, g] = canvas(256, 256);
    g.fillStyle = '#43383c'; g.fillRect(0, 0, 256, 256);
    speckle(g, 256, 256, 3000, ['#5a4b4e', '#332b2e', '#6d5a55'], 0.4, 1.5);
    const r = rng(9);
    for (let i = 0; i < 40; i++) {
      g.strokeStyle = `rgba(120,100,95,${0.08 + r() * 0.1})`;
      g.lineWidth = 1;
      g.beginPath(); g.moveTo(r() * 256, r() * 256); g.lineTo(r() * 256, r() * 256); g.stroke();
    }
    return tex(c, 5, 5);
  }),

  wall: (scheme = 0) => cached('wall' + scheme, () => {
    const [c, g] = canvas(512, 512);
    const schemes = [
      { top: '#c9c6b2', bottom: '#77836a', stripe: '#4e5b4c' },   // classroom / corridor
      { top: '#cfd4c6', bottom: '#9aa7a0', stripe: '#5f6f68' },   // toilets
      { top: '#b9b2a1', bottom: '#6b6152', stripe: '#4c4438' },   // office
      { top: '#c4beac', bottom: '#a49c7f', stripe: '#7a7157' },   // library
      { top: '#a7a79b', bottom: '#5c5f58', stripe: '#414540' },   // boiler
      { top: '#cfc7b4', bottom: '#8f8468', stripe: '#665c45' },   // cafeteria
    ];
    const s = schemes[scheme % schemes.length];
    g.fillStyle = s.top; g.fillRect(0, 0, 512, 512);
    const grad = g.createLinearGradient(0, 0, 0, 512);
    grad.addColorStop(0, 'rgba(255,255,255,.06)');
    grad.addColorStop(1, 'rgba(20,25,15,.18)');
    g.fillStyle = grad; g.fillRect(0, 0, 512, 512);
    // wainscot
    g.fillStyle = s.bottom; g.fillRect(0, 330, 512, 182);
    g.fillStyle = 'rgba(255,255,255,.10)'; g.fillRect(0, 324, 512, 6);
    g.fillStyle = s.stripe; g.fillRect(0, 318, 512, 6);
    // scuffs
    const r = rng(3 + scheme);
    for (let i = 0; i < 46; i++) {
      g.globalAlpha = 0.04 + r() * 0.12;
      g.fillStyle = r() > 0.5 ? '#2c2f25' : '#efeee2';
      const x = r() * 512, y = 250 + r() * 250, w = 3 + r() * 40, h = 1 + r() * 6;
      g.fillRect(x, y, w, h);
    }
    // vertical seams
    g.globalAlpha = 0.1; g.fillStyle = '#3c3f34';
    for (let i = 0; i < 4; i++) g.fillRect(i * 128, 0, 1, 512);
    g.globalAlpha = 1;
    return tex(c, 2, 1);
  }),

  tile: () => cached('tile', () => {
    const [c, g] = canvas(512, 512);
    g.fillStyle = '#c3c9c2'; g.fillRect(0, 0, 512, 512);
    const n = 16, s = 512 / n;
    const r = rng(77);
    for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
      const v = 0.92 + r() * 0.12;
      g.fillStyle = `rgb(${Math.floor(190 * v)},${Math.floor(199 * v)},${Math.floor(190 * v)})`;
      g.fillRect(x * s + 1.5, y * s + 1.5, s - 3, s - 3);
    }
    speckle(g, 512, 512, 400, ['#8b968a', '#e5eae1'], 0.12, 1.4);
    return tex(c, 2, 2);
  }),

  ceiling: () => cached('ceiling', () => {
    const [c, g] = canvas(256, 256);
    g.fillStyle = '#b9bcb2'; g.fillRect(0, 0, 256, 256);
    g.strokeStyle = 'rgba(70,74,68,.35)'; g.lineWidth = 3;
    g.strokeRect(2, 2, 252, 252);
    speckle(g, 256, 256, 500, ['#8f948a', '#d5d8ce'], 0.22, 1.5);
    return tex(c, 6, 6);
  }),

  locker: (num = 1) => cached('locker' + num, () => {
    const [c, g] = canvas(256, 512);
    g.fillStyle = '#4d6f7d'; g.fillRect(0, 0, 256, 512);
    const grad = g.createLinearGradient(0, 0, 256, 0);
    grad.addColorStop(0, 'rgba(255,255,255,.18)');
    grad.addColorStop(0.5, 'rgba(255,255,255,.02)');
