  this.stepPhase += dt * maxSpeed * 1.9;
  if (this.stepPhase > Math.PI) {
    this.stepPhase = 0;
    if (this.game.audio && maxSpeed > 1) this.game.audio.footstep(run, false);
    this.game.noise(this.pos.x, this.pos.z, run ? 12 : 5);
  }
  return dist < 0.3;
}

