    g.add(box(w + 0.16, 0.09, 0.12, frameMat, 0, 0.87, 0));
    g.add(box(w + 0.16, 0.09, 0.12, frameMat, 0, -0.87, 0));
    g.add(box(0.08, 1.8, 0.12, frameMat, -w / 2, 0, 0));
    g.add(box(0.08, 1.8, 0.12, frameMat, w / 2, 0, 0));
    g.add(box(0.05, 1.75, 0.1, frameMat, 0, 0, 0.01));
    g.position.set(x, 1.8, z);
