      ['TEACHER NOTE', '', '', '', '"A for effort. Z for everything else."']
    ], { name: 'JAKE', stamp: 'Z+' });
    c._gradeRows = 0;
    c._stamped = false;
    c._wrong = false;
    c.game.audio?.stinger();
