startGame() {
  if (this.state !== 'title') return;
  audio.init();
  audio.resume();
  audio.setVolume(Number(document.getElementById('volume')?.value || 70) / 100);
  UI.hideScreens();
  UI.fade(true, 300);
  this.stats.started = performance.now();
  this.state = 'cutscene';
  setTimeout(() => {
    UI.fade(false, 900);
    this.runCutscene('intro', () => introShots(this.cinematic), () => this.beginPlay());
  }, 420);
}

beginPlay() {
  this.state = 'play';
  this.setInputActive(true);
  this.world.setLighting('lockdown');
  this.world.setBodiesVisible(false);
  this.killer.spawn(34, 0);
  this.player.pos.set(-8.0, 0, -1.2);
  this.player.yaw = Math.PI;
  this.camYaw = Math.PI;
  this.pitch = -0.02;
  this.player.hp = 100;
  this.player.stamina = 100;
  this.player.battery = 100;
  this.player.crowbar = false;
  this.player.torchOn = true;
  this.avatar = this.player;
  this.controlledBot = null;
  this.bots.forEach((b, i) => {
    b.controlled = false;
    b.model.visible = true;
    b.pos.set([-10.4, -6.9, -12.2][i % 3], 0, [-2.2, -2.4, -1.6][i % 3]);
    b.yaw = 0;
    b.hp = 100;
    b.stamina = 100;
    b.downed = false;
