      window.__mm.push({ mx: e.movementX, my: e.movementY, locked: document.pointerLockElement === document.querySelector('canvas'), pitch: +window.__game.pitch.toFixed(3) });
    });
  });
  await page.evaluate(() => window.__game.cinematic.finish());
  await page.waitForTimeout(1500);
  console.log(JSON.stringify(await page.evaluate(() => ({ mm: window.__mm, locked: !!document.pointerLockElement, pitch: window.__game.pitch })), null, 1));
  await browser.close();
