button{font-family:var(--mono);cursor:pointer;border:none;outline:none}

/* ---------- FX ---------- */
#fx-vignette{position:absolute;inset:0;pointer-events:none;z-index:3;
  background:radial-gradient(ellipse at 50% 50%,rgba(0,0,0,0) 42%,rgba(0,0,0,.55) 78%,rgba(0,0,0,.92) 100%);}
#fx-grain{position:absolute;inset:-20%;pointer-events:none;z-index:4;opacity:.10;mix-blend-mode:overlay;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='220' height='220'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%25' height='100%25' filter='url(%23n)' opacity='.9'/></svg>");
  animation:grain .5s steps(2) infinite}
@keyframes grain{0%{transform:translate(0,0)}25%{transform:translate(-2%,1%)}50%{transform:translate(1%,-2%)}75%{transform:translate(2%,2%)}100%{transform:translate(-1%,-1%)}}
#fx-scan{position:absolute;inset:0;pointer-events:none;z-index:4;opacity:.10;
  background:repeating-linear-gradient(0deg,rgba(255,255,255,.06) 0 1px,transparent 1px 3px)}
#cine-ui{position:absolute;inset:0;z-index:17;pointer-events:none;font-family:var(--mono)}
#cine-grain{position:absolute;inset:-10%;opacity:.16;mix-blend-mode:overlay;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='240' height='240'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.75' numOctaves='3' stitchTiles='stitch'/></filter><rect width='100%25' height='100%25' filter='url(%23n)' opacity='.9'/></svg>");
  animation:grain .28s steps(2) infinite}
#cine-speedlines{position:absolute;inset:-25%;opacity:0;transition:opacity .35s;
  background:repeating-conic-gradient(from 0deg at 50% 50%,transparent 0deg 2deg,rgba(255,255,255,.26) 2.2deg 2.35deg,transparent 2.5deg 5deg);
  mix-blend-mode:screen;animation:cineSpin 14s linear infinite}
#cine-speedlines.on{opacity:.45}
@keyframes cineSpin{to{transform:rotate(360deg)}}
#cine-flash{position:absolute;inset:0;background:#eefaff;opacity:0}
#cine-flash.fire{animation:cineFire .34s ease-out}
@keyframes cineFire{0%{opacity:.92}100%{opacity:0}}
#cine-flare{position:absolute;width:65vw;height:12vh;left:15%;top:38%;opacity:0;filter:blur(24px);
  background:linear-gradient(90deg,transparent,rgba(130,210,255,.65),rgba(255,255,255,.92),rgba(255,220,160,.5),transparent);
  transform:rotate(-7deg);transition:opacity .5s}
#cine-flare.on{opacity:.72}
#cine-subtitle-wrap{position:absolute;left:50%;bottom:calc(9.2vh + 16px);transform:translateX(-50%);width:min(880px,88vw);text-align:center;opacity:0;transition:opacity .3s}
#cine-subtitle-wrap.show{opacity:1}
#cine-speaker{font-size:10px;letter-spacing:.36em;color:var(--green);margin-bottom:6px;text-transform:uppercase;text-shadow:0 2px 6px #000}
#cine-subtitle{font-size:clamp(15px,1.7vw,20px);line-height:1.55;color:#f7f2e5;text-shadow:0 2px 10px #000,0 0 30px #000;letter-spacing:.02em}
#cine-subtitle .scare{color:#ff7382;font-weight:bold}
#cine-subtitle .em{color:var(--amber)}
#cine-card{position:absolute;left:8vw;top:35%;max-width:70vw;opacity:0;transform:translateY(14px);transition:opacity .65s,transform .65s}
#cine-card.show{opacity:1;transform:none}
.cine-kicker{font-size:10px;letter-spacing:.5em;color:var(--green);margin-bottom:10px;text-shadow:0 0 14px rgba(141,255,178,.5)}
.cine-title{font-family:var(--display);font-size:clamp(32px,6.4vw,84px);line-height:.94;letter-spacing:.02em;color:#f4fff6;text-shadow:0 0 40px rgba(141,255,178,.25),0 10px 30px rgba(0,0,0,.6)}
.cine-rule{width:0;height:2px;margin-top:18px;background:linear-gradient(90deg,var(--green),transparent);transition:width .9s .2s}
#cine-card.show .cine-rule{width:min(420px,46vw)}
#cine-card.left{left:8vw}
#cine-card.center{left:50%;transform:translate(-50%,14px);text-align:center}
#cine-card.center.show{transform:translate(-50%,0)}
#cine-grade{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;opacity:0;transition:opacity .45s}
#cine-grade.show{opacity:1}
.cg-paper{position:relative;width:min(400px,70vw);background:linear-gradient(160deg,#f3ecd7,#ddd3b7);color:#1d211b;padding:20px 22px 16px;transform:rotate(-2.4deg) translate(-24vw,4vh);
  box-shadow:0 30px 90px rgba(0,0,0,.7),inset 0 0 60px rgba(120,100,60,.18);border:1px solid #b9ad8e;font-family:var(--mono)}
.cg-head{display:flex;justify-content:space-between;font-size:8px;letter-spacing:.14em;border-bottom:2px solid #2d332a;padding-bottom:6px}
.cg-name{font-size:11px;letter-spacing:.14em;margin:10px 0 8px;font-weight:bold}
.cg-rows{display:flex;flex-direction:column}
.cg-row{display:flex;align-items:baseline;gap:8px;border-bottom:1px dashed #9d927a;padding:3px 0;font-size:12px;letter-spacing:.03em;opacity:0;transform:translateX(-8px);transition:all .26s}
.cg-row.on{opacity:1;transform:none}
.cg-row .subject{flex:1;font-weight:bold}
.cg-row .note{flex:1.35;font-size:8px;letter-spacing:.02em;color:#6d6752;text-align:right;font-style:italic;padding-right:4px}
.cg-row .grade{font-family:var(--display);font-size:19px;min-width:42px;text-align:right;color:#6a2f8c}
.cg-row .grade.bad{color:#a1151c}
.cg-row .grade.zed{color:#2c6e3d}
.cg-row .grade.good{color:#1d6b8a}
.cg-stamp{position:absolute;right:18px;bottom:14px;width:80px;height:80px;border:3px solid rgba(160,20,25,.55);border-radius:50%;display:flex;align-items:center;justify-content:center;
  font-family:var(--display);font-size:46px;color:rgba(160,20,25,.68);transform:rotate(-14deg) scale(1.7);opacity:0;transition:transform .22s cubic-bezier(.2,1.8,.4,1),opacity .16s}
.cg-stamp.on{opacity:1;transform:rotate(-14deg) scale(1)}
.cg-foot{margin-top:10px;font-size:8px;letter-spacing:.1em;color:#4a4a3d}
.cg-sig{font-family:cursive;font-size:13px;color:#2d3c33;border-bottom:1px solid #6b6a55;padding:0 12px}
#cine-grade.wrong .cg-paper{animation:wrongPaper .42s steps(2) 3}
