#cine-skip{position:absolute;right:calc(2.2vw + var(--safe-r));bottom:calc(2.2vh + var(--safe-b));font-size:9px;letter-spacing:.24em;color:rgba(220,240,225,.42);opacity:0;transition:opacity .4s}
#cine-ui:hover #cine-skip,#cine-skip.show{opacity:1}
#letterbox .bar{height:10.5vh}

