];
for (const row of rows) {
  const inst = new THREE.InstancedMesh(winGeo, winMat, row.zs.length);
  row.zs.forEach((z, i) => {
    dummy.position.set(58.62, row.y, z);
    dummy.rotation.set(0, Math.PI / 2, 0);
    dummy.scale.set(1, 1, 1);
    dummy.updateMatrix();
    inst.setMatrixAt(i, dummy.matrix);
