Read file /home/runner/work/PlayGround/PlayGround/src/culling.js, lines 1-373
1: import * as THREE from 'three';
2: 
3: // ─────────────────────────────────────────────────────────────
4: // Static occlusion + frustum culler
5: //
6: // The school is a set of closed volumes joined by doorways. A room
7: // can only be seen if the camera is inside it, or if its door is open
8: // and that doorway is inside the view frustum. We use that "portal"
9: // rule to hide every prop in rooms the camera cannot possibly see —
10: // the mid-range win Three.js cannot do by itself, because a mesh
11: // behind a wall is still inside the camera frustum.
12: //
13: // Corridors are split into short chunks so a camera facing one way
14: // does not keep the whole hall (and every room hanging off it) alive.
15: //
16: // The pass is deliberately conservative:
17: //   • whole props are toggled, never individual faces
18: //   • the camera's own area is never hidden
19: //   • gameplay objects (items, characters, bodies, doors) are in
20: //     separate groups and are never touched
21: //   • a prop is only hidden after two consecutive sweeps
22: // ─────────────────────────────────────────────────────────────
23: const CHUNK = 13;
24: 
25: export class VisibilityCuller {
26:   constructor(game) {
27:     this.game = game;
28:     this.camera = game.camera;
29:     this.now = () => (typeof performance !== 'undefined' ? performance.now() : Date.now()) * 0.001;
30:     this.lastSweep = -1;
31:     this.lastCamArea = null;
32:     this.frustum = new THREE.Frustum();
33:     this.proj = new THREE.Matrix4();
34:     this.testSphere = new THREE.Sphere();
35: 
36:     this.entries = [];
37:     this.areas = [];
38:     this.conns = [];
39:     this.areaByRoom = new Map();
40:     this.allProps = [];
41: 
42:     this.timer = 0;
43:     this.interval = 0.12;
44:     this.enabled = true;
45:     this.ready = false;
46:     this.stats = { props: 0, visible: 0, hiddenArea: 0, hiddenFrustum: 0, areas: 0, areasVisible: 0 };
47:   }
48: 
49:   // ── world → area graph ───────────────────────────────────────
50:   collect() {
51:     const w = this.game.world;
52:     const A = [];
53:     const conns = [];
54:     const area = (id, x1, z1, x2, z2, kind) => {
55:       const a = {
56:         id, kind,
57:         x1: Math.min(x1, x2), x2: Math.max(x1, x2),
58:         z1: Math.min(z1, z2), z2: Math.max(z1, z2),
59:         neighbors: [],
60:         visible: true
61:       };
62:       a.cx = (a.x1 + a.x2) / 2;
63:       a.cz = (a.z1 + a.z2) / 2;
64:       a.r = Math.hypot(a.x2 - a.x1, a.z2 - a.z1) / 2 + 0.6;
65:       A.push(a);
66:       return a;
67:     };
68:     const connect = (a, b, px, pz, kind, radius, isOpen) => {
69:       const c = { a, b, px, pz, kind, open: isOpen || (() => true) };
70:       c.sphere = new THREE.Sphere(new THREE.Vector3(px, 1.6, pz), radius);
71:       a.neighbors.push({ other: b, conn: c });
72:       b.neighbors.push({ other: a, conn: c });
73:       conns.push(c);
74:       return c;
75:     };
76: 
77:     // rooms
78:     for (const room of w.rooms) {
79:       const a = area('room:' + room.id, room.x1, room.z1, room.x2, room.z2, 'room');
80:       a.room = room;
81:       this.areaByRoom.set(room.id, a);
82:     }
83: 
84:     // central + back corridor, cut into chunks
85:     const central = [];
86:     const back = [];
87:     for (let x = -52; x < 52; x += CHUNK) {
88:       central.push(area(`corr:${x}`, x, -3, Math.min(52, x + CHUNK), 3, 'corridor'));
89:       back.push(area(`back:${x}`, x, -30, Math.min(52, x + CHUNK), -24, 'corridor'));
90:     }
91:     const pass = area('pass', -10, -24, -7, -3, 'corridor');
92:     const wingW = area('wingW', -58, -30, -52, 3, 'corridor');
93:     const wingE = area('wingE', 52, -30, 58, 3, 'corridor');
94:     const outdoor = area('outdoor', 58, -14, 142, 14, 'outdoor');
95: 
96:     const chunkAt = (list, x) => list.find(a => x >= a.x1 && x <= a.x2) || list[list.length - 1];
97: 
98:     // chunk seams are open arches
99:     for (const list of [central, back]) {
100:       for (let i = 0; i < list.length - 1; i++) {
101:         const a = list[i], b = list[i + 1];
102:         connect(a, b, a.x2, 0, 'arch', 4.2);
103:       }
104:     }
105: 
106:     // passage joins both corridors
107:     connect(pass, chunkAt(central, -8.5), -8.5, -3, 'arch', 3.4);
108:     connect(pass, chunkAt(back, -8.5), -8.5, -24, 'arch', 3.4);
109: 
110:     // open-ended wings
111:     connect(wingW, central[0], -52, 0, 'arch', 3.4);
112:     connect(wingW, back[0], -52, -27, 'arch', 3.4);
113:     connect(wingE, central[central.length - 1], 52, 0, 'arch', 3.4);
114:     connect(wingE, back[back.length - 1], 52, -27, 'arch', 3.4);
115: 
116:     // the fenced yard is only reachable through the exit gate
117:     connect(outdoor, wingE, 58, 0, 'exit', 3.6, () => !!(w.exit && w.exit.open));
118: 
119:     // room doors
120:     for (const room of w.rooms) {
121:       const a = this.areaByRoom.get(room.id);
122:       const d = room.doorObj;
123:       if (!d) continue;
124:       const doorX = (room.door[0] + room.door[1]) / 2;
125:       const corridor = room.side === 'back'
126:         ? chunkAt(back, doorX)
127:         : chunkAt(central, doorX);
128:       const c = connect(a, corridor, doorX, d.wallZ, 'door', 1.5, () => d.open === true);
129:       // point a little way inside the room: if the wall beside the door
130:       // blocks the line to it, the doorway is edge-on and the room can
131:       // stay culled even though the door leaf is on screen
132:       c.inside = {
133:         x: doorX,
134:         z: d.wallZ + (room.side === 'south' ? 1.9 : -1.9)
135:       };
136:     }
137: 
138:     this.areas = A;
139:     this.conns = conns;
140: 
141:     // ── bucket every static prop into an area ──
142:     this.entries.length = 0;
143:     this.allProps.length = 0;
144:     const roots = [w.propGroup, w.hideGroup];
145:     for (const root of roots) {
146:       for (const obj of root.children) {
147:         if (!obj || obj.isLight) continue;
148:         if (!obj.visible && obj.userData.cullIgnore) continue;
149:         obj.updateWorldMatrix(true, true);
150:         const box = new THREE.Box3().setFromObject(obj);
151:         if (box.isEmpty()) continue;
152:         const sphere = box.getBoundingSphere(new THREE.Sphere());
153:         if (sphere.radius < 0.05) continue;
154:         let owner = this.areaAt(sphere.center.x, sphere.center.z);
155:         if (!owner) owner = this.nearestArea(sphere.center.x, sphere.center.z);
156:         const e = {
157:           obj, box, sphere,
158:           area: owner,
159:           hidden: !obj.visible,
160:           blocked: 0
161:         };
162:         this.entries.push(e);
163:         this.allProps.push(obj);
164:       }
165:     }
166: 
167:     // ── static architecture (walls, doors, windows, fixtures) ──
168:     // These are direct scene children, so they are bucketed the same
169:     // way. A mesh is kept whenever its bounds touch any *visible*
170:     // area, which protects shared walls between a seen room and a
171:     // hidden one.
172:     this.arch = [];
173:     const skip = new Set([w.hideGroup, w.itemGroup, w.bodyGroup, w.propGroup]);
174:     for (const obj of w.scene.children) {
175:       if (skip.has(obj) || obj.isLight || obj.isCamera) continue;
176:       if (obj.userData && obj.userData.cullSkip) continue;
177:       obj.updateWorldMatrix(true, true);
178:       const box = new THREE.Box3().setFromObject(obj);
179:       if (box.isEmpty()) continue;
180:       let owner = this.areaAt((box.min.x + box.max.x) / 2, (box.min.z + box.max.z) / 2);
181:       if (!owner) owner = this.nearestArea((box.min.x + box.max.x) / 2, (box.min.z + box.max.z) / 2);
182:       this.arch.push({
183:         obj, box, area: owner, hidden: !obj.visible,
