const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist'] });
  const page = await browser.newPage({ viewport: { width: 1024, height: 576 } });
  page.setDefaultTimeout(120000);
  page.on('pageerror', e => console.log('ERR', e.message));
  await page.goto('http://localhost:8123/', { waitUntil: 'load' });
  await page.waitForTimeout(2800);
  await page.click('#btn-play');
  await page.waitForFunction(() => window.__game.cinematic.active === true, null, { timeout: 30000 });
  await page.evaluate(() => window.__game.cinematic.finish());
  await page.waitForTimeout(1000);

  const setup = await page.evaluate(() => {
    const g=window.__game, w=g.world;
    // pick a locked room whose corridor we can stand in
    const room = w.lockedRooms.find(r=>r.side==='north') || w.lockedRooms.find(r=>r.side==='back') || w.lockedRooms[0];
    const d=room.doorObj;
    const doorX=(room.door[0]+room.door[1])/2;
    const cz = room.side==='back' ? -27 : 0;
    g.player.keys.add(room.lockLabel);
    g.player.pos.set(2,0,0); // far away
    g.killer.active=false;
    const bot=g.bots[0];
    bot.pos.set(doorX+5, 0, cz);
    bot.yaw=0;
    bot.state='scout';
    bot.targetPos={x:(room.x1+room.x2)/2, z:(room.z1+room.z2)/2};
    bot.pathTo(bot.targetPos.x, bot.targetPos.z, true);
    return { room:room.id, side:room.side, label:room.lockLabel, doorX, cz, locked:d.locked, open:d.open,
      bot:[bot.pos.x,bot.pos.z], pathLen:bot.path.length, path:bot.path.map(p=>[+p.x.toFixed(1),+p.z.toFixed(1)]), doorTarget:!!bot.doorTarget };
  });
  console.log('setup', JSON.stringify(setup));

  for (let i=0;i<10;i++) {
    await page.waitForTimeout(2200);
    console.log('t'+i, JSON.stringify(await page.evaluate(() => {
      const g=window.__game, w=g.world;
      const room = w.lockedRooms.find(r=>r.side==='north') || w.lockedRooms.find(r=>r.side==='back') || w.lockedRooms[0];
      const d=room.doorObj, b=g.bots[0];
      return { st:b.state, pos:[+b.pos.x.toFixed(2),+b.pos.z.toFixed(2)], path:b.path.length,
        reflect:+((b.path[b.pathIndex]?.x||0)).toFixed(1)+','+((b.path[b.pathIndex]?.z||0)).toFixed(1),
        doorTarget:!!b.doorTarget, locked:d.locked, open:d.open, ang:+d.leaf.rotation.y.toFixed(2),
        inRoom:b.pos.x>room.x1&&b.pos.x<room.x2&&b.pos.z>room.z1&&b.pos.z<room.z2, stuck:+b.stuckTimer.toFixed(2) };
    })));
  }
  await browser.close();
})();
