264:     // wall-clock, not simulation time: a slow frame must not starve
265:     // the culler (otherwise stale interiors linger for seconds)
266:     const now = this.now();
267:     const cam = this.camera;
268:     const camAreaNow = this.areaAt(cam.position.x, cam.position.z);
269:     const areaChanged = camAreaNow !== this.lastCamArea;
270:     if (!areaChanged && now - this.lastSweep < this.interval) return;
271:     this.lastSweep = now;
272:     this.lastCamArea = camAreaNow;
273: 
274:     cam.updateMatrixWorld();
275:     // The renderer refreshes matrixWorldInverse, but this pass runs
276:     // before it — and after a POV switch or camera cut that matrix is
277:     // still from the old view, which would cull the wrong geometry.
278:     cam.matrixWorldInverse.copy(cam.matrixWorld).invert();
279:     this.proj.multiplyMatrices(cam.projectionMatrix, cam.matrixWorldInverse);
280:     this.frustum.setFromProjectionMatrix(this.proj);
281: 
282:     const camArea = camAreaNow;
283:     for (const a of this.areas) a.visible = false;
284: 
285:     let areaCount = 0;
286:     if (!camArea) {
287:       // outside the graph (rooftop / cutscene off-map): stay safe, show all
288:       for (const a of this.areas) a.visible = true;
289:     } else {
290:       camArea.visible = true;
291:       // standing in the lot, the glass vestibule is always in view
292:       if (camArea.kind === 'outdoor') {
293:         const w = this.game.world;
294:         const wing = this.areas.find(a => a.id === 'wingE');
295:         if (wing) wing.visible = true;
296:       }
297:       const queue = [camArea];
298:       let guard = 0;
299:       while (queue.length && guard++ < 80) {
300:         const a = queue.pop();
301:         areaCount++;
302:         for (const n of a.neighbors) {
303:           if (n.other.visible) continue;
304:           if (!n.conn.open()) continue;
305:           // Only the doorway / seam itself has to be on screen. A room
306:           // whose door is off-camera cannot be seen even though its
307:           // bounding sphere may reach into the corridor.
308:           if (!this.frustum.intersectsSphere(n.conn.sphere)) continue;
309:           // Sight line to the doorway itself. Oblique doorways and
310:           // connections reached around a corner are dropped here.
311:           const tx = n.conn.inside ? n.conn.inside.x : n.conn.px;
312:           const tz = n.conn.inside ? n.conn.inside.z : n.conn.pz;
313:           if (this.losBlocked(cam.position.x, cam.position.z, tx, tz)) continue;
314:           n.other.visible = true;
