316:         }
317:       }
318:     }
319: 
320:     let visible = 0, hiddenArea = 0, hiddenFrustum = 0;
321:     for (const e of this.entries) {
322:       const areaSeen = !e.area || e.area.visible;
323:       if (!areaSeen) {
324:         e.blocked = 2;
325:         if (!e.hidden) { e.obj.visible = false; e.hidden = true; }
326:         hiddenArea++;
327:         continue;
328:       }
329:       if (!this.frustum.intersectsSphere(e.sphere)) {
330:         if (!e.hidden) { e.obj.visible = false; e.hidden = true; }
331:         e.blocked = 0;
332:         hiddenFrustum++;
333:         continue;
334:       }
335:       // debounce only the "became visible again" direction so that
336:       // doorways at the edge of the frustum do not strobe
337:       e.blocked = 0;
338:       if (e.hidden) { e.obj.visible = true; e.hidden = false; }
339:       visible++;
340:     }
341: 
342:     // ── architecture pass ──
343:     const seen = [];
344:     for (const a of this.areas) {
345:       if (a.visible) seen.push(a);
