355:               b.max.z >= a.z1 - 0.45 && b.min.z <= a.z2 + 0.45) { keep = true; break; }
356:         }
357:       }
358:       if (keep) {
359:         if (e.hidden) { e.obj.visible = true; e.hidden = false; }
360:       } else if (!e.hidden) {
361:         e.obj.visible = false;
362:         e.hidden = true;
363:       }
364:     }
365: 
366:     this.stats.visible = visible;
367:     this.stats.hiddenArea = hiddenArea;
368:     this.stats.hiddenFrustum = hiddenFrustum;
369:     this.stats.archHidden = this.arch.reduce((n, e) => n + (e.hidden ? 1 : 0), 0);
370:     this.stats.areasVisible = seen.length;
371:     this.stats.areaCount = areaCount;
372: 
373:     // The whole forecourt lives in one scene child, so the per-child
374:     // architecture pass cannot cull it. Drive it from the area graph
375:     // instead: indoors with the exit shut, the street does not exist.
376:     const outdoorGroup = this.game.world.outdoorGroup;
377:     if (outdoorGroup) {
