const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.goto('file:///tmp/opencode/');
  const out = await page.evaluate(async () => {
    const load = (src) => new Promise((res) => { const i = new Image(); i.onload = () => res(i); i.src = src; });
    const [a, b] = await Promise.all([load('/tmp/opencode/q-cafeteria-oblique-on.jpg'), load('/tmp/opencode/q-cafeteria-oblique-off.jpg')]);
    const w = a.width, h = a.height;
    const c1 = document.createElement('canvas'); c1.width=w; c1.height=h;
    const c2 = document.createElement('canvas'); c2.width=w; c2.height=h;
    const x1 = c1.getContext('2d'), x2 = c2.getContext('2d');
    x1.drawImage(a,0,0); x2.drawImage(b,0,0);
    const d1 = x1.getImageData(0,0,w,h).data, d2 = x2.getImageData(0,0,w,h).data;
    const cell = 16, cols = Math.ceil(w/cell), rows = Math.ceil(h/cell);
    const grid = new Array(cols*rows).fill(0);
    for (let y=0;y<h;y++) for (let x=0;x<w;x++) {
      const i=(y*w+x)*4;
      const d = Math.abs(d1[i]-d2[i]) + Math.abs(d1[i+1]-d2[i+1]) + Math.abs(d1[i+2]-d2[i+2]);
      if (d > 40) grid[((y/cell)|0)*cols + ((x/cell)|0)]++;
    }
    // cluster hot cells (>=6 differing pixels)
    const hot = [];
    for (let r=0;r<rows;r++) for (let c=0;c<cols;c++) if (grid[r*cols+c]>=6) hot.push({c,r,n:grid[r*cols+c]});
    const clusters = [];
    const seen = new Set();
    for (const hcell of hot) {
      const key = hcell.c+','+hcell.r;
      if (seen.has(key)) continue;
      const q=[hcell]; seen.add(key); const cl={x1:hcell.c,y1:hcell.r,x2:hcell.c,y2:hcell.r,n:0};
      while (q.length) {
        const cur=q.pop(); cl.n+=cur.n;
        cl.x1=Math.min(cl.x1,cur.c); cl.x2=Math.max(cl.x2,cur.c);
        cl.y1=Math.min(cl.y1,cur.r); cl.y2=Math.max(cl.y2,cur.r);
        for (let dr=-1;dr<=1;dr++) for (let dc=-1;dc<=1;dc++) {
          const k=(cur.c+dc)+','+(cur.r+dr);
          if (seen.has(k)) continue;
          const idx=(cur.r+dr)*cols+(cur.c+dc);
          if (cur.r+dr<0||cur.r+dr>=rows||cur.c+dc<0||cur.c+dc>=cols) continue;
          if (grid[idx]>=6) { seen.add(k); q.push({c:cur.c+dc,r:cur.r+dr,n:grid[idx]}); }
        }
      }
      clusters.push({px:[cl.x1*cell,cl.y1*cell,cl.x2*cell+cell,cl.y2*cell+cell], cells:cl.n});
    }
    clusters.sort((p,q)=>q.cells-p.cells);
    return { w, h, clusters: clusters.slice(0,12) };
  });
  console.log(JSON.stringify(out));
  await browser.close();
})();
