    }
    out.sort((a,b)=>((b.x2-b.x1)*(b.y2-b.y1))-((a.x2-a.x1)*(a.y2-a.y1)));
    return { vis:c.areas.filter(a=>a.visible).map(a=>a.id), clusters: out.slice(0,20) };
  }), null, 1));
